// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"pt-BR","term":"Coin vs token (moeda e token)","aka":["diferença entre coin e token","moeda nativa"],"short":"Coin é a moeda nativa de uma blockchain própria, como BTC ou ETH, enquanto token é um ativo criado sobre uma blockchain existente por meio de um contrato inteligente.","body":[["Uma coin nasce junto com a rede: o ",["BTC","bitcoin"]," no Bitcoin, o ",["ETH","ethereum"]," no Ethereum, o SOL na Solana. Ela é usada para pagar taxas e, em redes de ",["prova de participação","proof-of-stake"],", para ",["fazer staking","staking"]," e proteger a rede."],["Um token não tem ",["blockchain","blockchain"]," própria. Ele é emitido por um ",["contrato inteligente","smart-contract"]," dentro de outra rede. O USDT, por exemplo, existe como token em várias redes, como Ethereum e Tron. Tokens podem representar stablecoins, direitos de governança, pontos de programas ou ações dentro de um aplicativo."],"A diferença tem efeito prático. Para mover um token, você paga a taxa na coin nativa da rede. E o mesmo token pode existir em redes diferentes, com endereços de contrato diferentes. Por isso, ao depositar ou sacar, você sempre precisa escolher a rede certa."],"example":"Suponha que você tem 100 USDT na rede Ethereum e quer enviá-los para outra carteira. Mesmo que os 100 USDT estejam lá, a transferência só sai se você tiver ETH para pagar o gás, digamos 0,0005 ETH. Se seu saldo de ETH for zero, os USDT ficam parados. Na rede Tron, o mesmo envio exige TRX ou recursos da própria rede.","mistakes":["Tentar enviar tokens sem ter a moeda nativa da rede para pagar a taxa.","Achar que USDT na Ethereum e USDT na Tron são intercambiáveis num depósito, quando é preciso escolher a mesma rede dos dois lados.","Confiar em um token só porque o nome é parecido com um projeto conhecido, sem conferir o endereço do contrato."],"faq":[{"q":"USDT é coin ou token?","a":"É um token. A Tether emite o USDT em várias blockchains, e em todas elas ele depende de um contrato inteligente na rede de outra moeda."},{"q":"Por que as pessoas chamam tudo de moeda?","a":"No dia a dia, coin e token viraram quase sinônimos. A distinção técnica importa principalmente na hora de pagar taxas e escolher a rede de transferência."}],"title":"Coin vs token: qual a diferença em cripto?","description":"Veja a diferença entre coin e token, por que você precisa da moeda nativa para pagar taxas e como escolher a rede certa.","related":[["layer-1","Camada 1 (Layer 1, L1)","Camada 1 (L1) é uma blockchain base, como Bitcoin, Ethereum ou Solana, que processa e finaliza transações com seu próprio consenso e sua própria moeda nativa."],["smart-contract","Contrato inteligente (smart contract)","Contrato inteligente é um programa publicado numa blockchain que executa automaticamente regras predefinidas, como trocar tokens ou liberar fundos, sem depender de um intermediário."],["governance-token","Token de governança","Um token de governança é um token que dá ao seu detentor direito de propor e votar mudanças em um protocolo ou DAO, como taxas, parâmetros de risco e uso da tesouraria."],["tokenomics","Tokenomics","Tokenomics é o conjunto de regras econômicas de um token: oferta total, distribuição entre equipe e investidores, cronograma de liberação, utilidade e mecanismos como queima ou recompensas."],["altcoin","Altcoin","Altcoin é qualquer criptomoeda que não seja o bitcoin, de grandes redes como Ethereum e Solana até tokens pequenos e memecoins."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"pt-BR","term":"Memecoin","aka":["meme coin","moeda meme","memes"],"short":"Memecoin é uma criptomoeda inspirada em memes, piadas ou cultura da internet, cujo preço depende principalmente de comunidade, atenção e especulação, e não de um produto ou receita.","body":["O Dogecoin, criado em 2013 como brincadeira, é o exemplo mais conhecido. Depois vieram o Shiba Inu, o Pepe e milhares de tokens lançados todos os dias, principalmente em redes de taxas baixas como Solana e Base.",["Memecoins costumam ter oferta gigantesca e preço unitário minúsculo, o que dá a sensação de ser barato. A ",["volatilidade","volatility"]," é extrema: altas de várias vezes em dias e quedas de 90% são comuns. Muitas perdem quase toda a ",["liquidez","liquidity"]," pouco depois do lançamento."],["O risco de ",["rug pull","rug-pull"]," é alto. Antes de comprar, vale verificar quanto da oferta está concentrado em poucas carteiras, se a liquidez está travada, se o contrato permite cunhar mais tokens ou bloquear vendas e em quais corretoras o token é negociado. Se você entrar, use só um valor que aceita perder por inteiro."]],"example":["Imagine que você compra R$ 300 de uma memecoin com liquidez de apenas US$ 50.000 numa ",["DEX","dex"],". O token sobe 4 vezes e sua posição passa a valer R$ 1.200 na tela. Mas, como o pool é raso, vender tudo de uma vez pode gerar ",["slippage","slippage"]," de 15%, e você recebe uns R$ 1.020. Se os criadores retirarem a liquidez antes, sua posição pode ir a quase zero."],"mistakes":["Comprar por FOMO depois de uma alta de 500% anunciada em grupo de Telegram.","Ignorar a concentração de tokens em poucas carteiras, que podem vender de uma vez.","Calcular o lucro pelo preço na tela, sem considerar a liquidez real para vender."],"faq":[{"q":"Memecoin é investimento?","a":"Memecoins são ativos altamente especulativos, sem fluxo de caixa ou produto por trás na maioria dos casos. Muitas perdem quase todo o valor."},{"q":"Como comprar memecoin com segurança?","a":"Prefira tokens listados em corretoras grandes ou confira o endereço do contrato nos canais oficiais. Use valores pequenos e cuidado com aprovações de contrato."}],"title":"O que é memecoin? Significado e riscos","description":"Entenda o que são memecoins, por que são tão voláteis, como funciona o risco de rug pull e o que conferir antes de comprar.","related":[["altcoin","Altcoin","Altcoin é qualquer criptomoeda que não seja o bitcoin, de grandes redes como Ethereum e Solana até tokens pequenos e memecoins."],["rug-pull","Rug pull (puxada de tapete)","Rug pull é um golpe em que os criadores de um token ou projeto retiram de repente a liquidez ou os fundos dos investidores e abandonam o projeto, deixando o token praticamente sem valor."],["volatility","Volatilidade","Volatilidade é a intensidade e a frequência com que o preço de um ativo sobe e desce num período; quanto maior, mais amplos e rápidos são os movimentos."],["liquidity","Liquidez","Liquidez é a facilidade de comprar ou vender um ativo rapidamente, em quantidade relevante, sem mexer muito no preço."],["dex","Corretora descentralizada (DEX)","Uma corretora descentralizada (DEX) é uma plataforma onde você troca criptomoedas diretamente da sua carteira por meio de contratos inteligentes, sem entregar a custódia a uma empresa."]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"pt-BR","term":"HODL","aka":["hodler","holdar","hold"],"short":"HODL é a estratégia de comprar uma criptomoeda e mantê-la por longo prazo, sem vender nas quedas e oscilações, termo nascido de um erro de digitação de hold num fórum em 2013.","body":[["Em 2013, um usuário de um fórum de ",["bitcoin","bitcoin"]," escreveu HODLING no lugar de holding, num post sobre não vender durante uma queda. O erro virou meme, e depois alguns passaram a ler como Hold On for Dear Life. No Brasil, muita gente fala simplesmente em holdar."],["A ideia é que tentar acertar topos e fundos é difícil e caro, e que quem acredita no longo prazo pode se dar melhor ignorando o ruído diário. Muitos hodlers combinam a estratégia com aportes regulares e com guarda em carteira própria, como uma ",["carteira fria","cold-wallet"],"."],["HODL só faz sentido com ativos em que você confia no longo prazo e com dinheiro que não vai precisar tão cedo. Segurar uma ",["altcoin","altcoin"]," que perdeu 95% e não tem mais uso não é estratégia, é falta de revisão. Vale reavaliar sua tese de tempos em tempos."]],"example":"Suponha que você compra 0,1 BTC a US$ 30.000, pagando US$ 3.000. Nos meses seguintes, o preço cai para US$ 18.000 e sua posição vale US$ 1.800, uma queda de 40%. Se você vender ali, realiza US$ 1.200 de perda. Se você segurar e o preço mais tarde chegar a US$ 45.000, a posição vale US$ 4.500. Isso aconteceu em alguns ciclos, mas não é garantido.","mistakes":["Hodlar qualquer token por teimosia, sem revisar se o projeto ainda faz sentido.","Deixar o saldo de longo prazo numa corretora sem pensar em autocustódia.","Investir em HODL um dinheiro que você vai precisar no próximo ano."],"faq":[{"q":"O que significa HODL?","a":"É uma brincadeira com a palavra hold, manter. Virou sinônimo de segurar cripto no longo prazo sem vender nas quedas."},{"q":"HODL é melhor que fazer trade?","a":"Depende do seu tempo, conhecimento e perfil. Muitos iniciantes têm mais dificuldade com trades frequentes por causa de taxas e emoções, mas HODL também tem riscos."}],"title":"O que é HODL? Significado em cripto","description":"Saiba o que significa HODL, a origem do termo e quando faz sentido segurar cripto no longo prazo sem vender nas quedas.","related":[["dollar-cost-averaging","Preço médio (DCA)","DCA (dollar-cost averaging) é a estratégia de comprar um valor fixo de um ativo em intervalos regulares, independentemente do preço, para diluir o custo médio ao longo do tempo."],["cold-wallet","Carteira fria (cold wallet)","Uma carteira fria (cold wallet) é uma forma de guardar criptomoedas em que a chave privada fica em um ambiente sem conexão com a internet, como uma carteira de hardware ou um dispositivo offline."],["bear-market","Mercado de baixa (bear market)","Mercado de baixa (bear market) é um período prolongado de queda generalizada dos preços, geralmente 20% ou mais a partir do topo, com pessimismo, volume menor e saída de investidores."],["volatility","Volatilidade","Volatilidade é a intensidade e a frequência com que o preço de um ativo sobe e desce num período; quanto maior, mais amplos e rápidos são os movimentos."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"pt-BR","term":"Pool de liquidez (liquidity pool)","aka":["liquidity pool","pool","piscina de liquidez"],"short":"Um pool de liquidez é um conjunto de tokens travados em um contrato inteligente que permite trocas em uma DEX, em que os depositantes, chamados provedores de liquidez, recebem parte das taxas.","body":[["Para criar ",["liquidez","liquidity"]," em um par como ",["ETH","ethereum"],"/",["USDC","usdc"],", provedores depositam os dois tokens, normalmente em valores equivalentes. Em troca, recebem tokens de LP ou uma posição em ",["NFT","nft"],", que representam sua fatia no pool. Quando alguém troca, paga uma taxa que é distribuída proporcionalmente entre os provedores."],["Fornecer liquidez não é o mesmo que deixar dinheiro parado rendendo. Conforme o preço se move, o pool vende automaticamente o token que sobe e compra o que cai, o que gera a ",["perda impermanente","impermanent-loss"],". Em pools de liquidez concentrada, sua posição só rende quando o preço está dentro da faixa escolhida."],["Também há riscos de contrato e de projeto: tokens novos com pool pequeno podem sofrer ",["rug pull","rug-pull"],", quando o criador retira a liquidez. Antes de depositar, compare o volume de trocas, que gera as taxas, com o risco do par e o tempo de funcionamento do protocolo."]],"example":"Um pool ETH/USDC tem 10.000.000 USDC em liquidez total e movimenta 2.000.000 USDC por dia com taxa de 0,3%. Isso gera 6.000 USDC de taxas diárias. Se você depositou 10.000 USDC em valor, ou 0,1% do pool, recebe cerca de 6 USDC por dia, aproximadamente 2.190 USDC em um ano se volume e participação ficassem iguais. Esse ganho precisa ser comparado com a perda impermanente caso o preço do ETH mude muito.","mistakes":["Olhar só o APR exibido e esquecer que ele depende do volume, que muda todos os dias.","Depositar em pools de tokens recém-lançados sem verificar se a liquidez está travada.","Perder os tokens de LP ou a posição NFT, que são o comprovante da sua parte no pool."],"faq":[{"q":"Como se ganha dinheiro com pool de liquidez?","a":"Principalmente com a parte das taxas de troca e, em alguns protocolos, com recompensas extras em tokens. O resultado final depende também da perda impermanente e do preço dos tokens depositados."},{"q":"Posso retirar minha liquidez a qualquer momento?","a":"Na maioria dos pools sim, devolvendo os tokens de LP. Você recebe os dois tokens na proporção atual do pool, que pode ser diferente da que você depositou."}],"title":"O que é pool de liquidez? Como funciona em DeFi","description":"Saiba o que é um pool de liquidez, como os provedores ganham taxas e quais riscos considerar antes de depositar em uma DEX.","related":[["amm","Formador de mercado automatizado (AMM)","Um formador de mercado automatizado (AMM) é um contrato inteligente que define o preço de uma troca por uma fórmula matemática aplicada às reservas de um pool de liquidez, em vez de casar ordens de compradores e vendedores."],["impermanent-loss","Perda impermanente (impermanent loss)","Perda impermanente é a diferença entre o valor que você teria simplesmente segurando dois tokens e o valor da sua posição em um pool de liquidez depois que o preço entre eles muda."],["yield-farming","Yield farming (farming de rendimento)","Yield farming é a estratégia de mover cripto entre protocolos DeFi, como pools de liquidez e plataformas de empréstimo, para receber taxas e recompensas em tokens em troca de fornecer capital."],["rug-pull","Rug pull (puxada de tapete)","Rug pull é um golpe em que os criadores de um token ou projeto retiram de repente a liquidez ou os fundos dos investidores e abandonam o projeto, deixando o token praticamente sem valor."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"pt-BR","term":"Perp DEX (futuros perpétuos on-chain)","aka":["perp DEX","DEX de perpétuos","DEX de derivativos","perpétuos on-chain"],"short":"Uma perp DEX é uma corretora descentralizada de futuros perpétuos, em que você opera com alavancagem a partir da sua própria carteira, com margem e liquidações controladas por contratos ou por uma blockchain própria.","body":[["Exemplos conhecidos são Hyperliquid, que roda em uma ",["blockchain","blockchain"]," própria com ",["livro de ofertas","order-book"]," on-chain, dYdX e GMX, que usa um modelo de ",["pool de liquidez","liquidity-pool"],". Você deposita a margem, normalmente em ",["USDC","usdc"],", e abre posições compradas ou vendidas em ",["futuros perpétuos","perpetual-futures"],", com ",["taxa de financiamento","funding-rate"],", preço de marcação e liquidação como em uma corretora centralizada."],"A diferença está na custódia e na transparência: posições, liquidações e às vezes o próprio livro de ofertas ficam visíveis on-chain, e você saca para a sua carteira sem depender de aprovação de uma empresa. Em compensação, existem riscos de contrato, da ponte usada para depositar, de oráculo e de liquidez em mercados menores.","Cada perp DEX tem regras próprias. A frequência do funding varia, por exemplo, algumas liquidam a cada hora em vez das 8 horas comuns em corretoras centralizadas. Confira também alavancagem máxima, taxas maker e taker e como funciona o fundo de seguro ou o mecanismo de socialização de perdas."],"example":"Você deposita 1.000 USDC em uma perp DEX e abre uma posição comprada em BTC com 5x de alavancagem, quando o BTC está a 60.000 USDC. O valor nocional é de 5.000 USDC, cerca de 0,0833 BTC. Se o BTC subir 4%, para 62.400, você ganha cerca de 200 USDC, 20% da margem, antes de taxas e funding. Se cair perto de 20%, menos a margem de manutenção, a posição pode ser liquidada e você perde quase toda a margem.","mistakes":["Supor que o funding da perp DEX é cobrado a cada 8 horas como na sua corretora habitual.","Esquecer o risco da ponte e do contrato, e não só o risco de preço da posição.","Usar alavancagem alta em mercados com pouca liquidez, onde o slippage na liquidação é maior."],"faq":[{"q":"Perp DEX exige cadastro ou KYC?","a":"Em geral você só conecta uma carteira, mas muitos sites bloqueiam o acesso de certas regiões. As obrigações legais e fiscais do seu país continuam valendo."},{"q":"Perp DEX é mais segura que corretora centralizada?","a":"Ela elimina o risco de custódia da empresa, mas traz riscos de contrato, ponte e oráculo. Nenhum modelo elimina o risco de liquidação da posição alavancada."}],"title":"O que é perp DEX? Futuros perpétuos on-chain","description":"Saiba o que é uma perp DEX, como funcionam futuros perpétuos on-chain e em que margem, funding e riscos diferem das corretoras.","related":[["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["dex","Corretora descentralizada (DEX)","Uma corretora descentralizada (DEX) é uma plataforma onde você troca criptomoedas diretamente da sua carteira por meio de contratos inteligentes, sem entregar a custódia a uma empresa."],["funding-rate","Taxa de financiamento (funding rate)","Taxa de financiamento (funding rate) é um pagamento periódico entre traders comprados e vendidos em futuros perpétuos, usado para manter o preço do contrato próximo do preço à vista."],["non-custodial-wallet","Carteira não custodial (autocustódia)","Uma carteira não custodial é uma carteira de cripto em que só você controla a chave privada e a frase de recuperação, sem depender de uma corretora ou empresa para guardar ou liberar seus fundos."]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"pt-BR","term":"Copy trading","aka":["copy trading","copy trade","cópia de operações","trading social"],"short":"Copy trading é um recurso em que você conecta parte do seu saldo a um trader escolhido e a plataforma replica automaticamente as operações dele na sua conta, de forma proporcional ao valor alocado.","body":["OKX, Bybit e Bitget, entre outras, oferecem copy trading em spot e em futuros. Você escolhe um trader pelo histórico exibido, define quanto quer alocar, um limite de perda e, às vezes, o tamanho fixo de cada cópia. O trader costuma receber uma participação nos lucros que gera para os seguidores, com percentual e regras definidos por cada plataforma.",["Os riscos são os mesmos de operar sozinho, só que nas mãos de outra pessoa. Em futuros com ",["alavancagem","leverage"],", uma única operação ruim pode liquidar o valor alocado. Além disso, seus preços de entrada podem ser piores que os do trader por causa de ",["slippage","slippage"],", e históricos curtos podem esconder estratégias arriscadas, como médio preço sem stop."],["Para avaliar um trader, olhe o tempo de histórico, a perda máxima (drawdown), a alavancagem média, o tamanho do capital que ele já administra e se ele usa ",["stop loss","stop-loss"],". Lucro alto em pouco tempo, sem drawdown aparente, merece desconfiança."]],"example":["Suponha que você aloque 1.000 ",["USDT","usdt"]," para copiar um trader que tem 10.000 USDT na conta. Ele abre uma posição usando 20% do saldo, ou 2.000 USDT de margem; sua cópia usa 200 USDT. Se a operação ganha 30% sobre a margem, você lucra 60 USDT e, com participação de 10%, paga 6 USDT ao trader, ficando com 54."],"mistakes":["Escolher o trader só pelo maior retorno dos últimos 7 dias.","Não definir um limite de perda para o valor alocado.","Esquecer que a alavancagem do trader também se aplica ao seu dinheiro."],"faq":[{"q":"Copy trading é seguro?","a":"Não elimina riscos. Você segue as decisões de outra pessoa, e em futuros pode perder todo o valor alocado. Limites de perda e alocação pequena reduzem o estrago."},{"q":"Quanto o trader ganha no copy trading?","a":"Em geral uma participação nos lucros dos seguidores, definida pela plataforma e pelo próprio trader. Prejuízos não geram pagamento."}],"title":"O que é copy trading? Como copiar traders em cripto","description":"Entenda como funciona o copy trading, como a divisão de lucros é feita e como escolher e limitar o risco ao copiar.","related":[["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["leverage","Alavancagem","Alavancagem é o uso de margem para abrir uma posição maior do que o seu capital, multiplicando tanto os ganhos quanto as perdas em relação ao valor depositado."],["risk-reward-ratio","Relação risco-retorno","Relação risco-retorno é a comparação entre quanto você pode perder até o stop loss e quanto pode ganhar até o alvo de uma operação, como 1 para 3."],["grid-trading-bot","Robô de grid (grid trading bot)","Um robô de grid é uma ferramenta automática que distribui várias ordens de compra e venda em intervalos fixos dentro de uma faixa de preço, comprando nas quedas e vendendo nas altas para lucrar com a oscilação."]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
